def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    # cache maps key -> (value, write_time)
    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove the key if it exists (to re-insert it at the end)
            if key in cache:
                del cache[key]

            # If cache is at capacity and we're adding a new key, evict LRU
            if len(cache) >= capacity and key not in cache:
                cache.popitem(last=False)

            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and hasn't expired
            if key in cache:
                value, write_time = cache[key]
                if t < write_time + ttl:
                    # Entry is valid, move to end (most recently used)
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
                else:
                    # Entry has expired
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

